SELECT percentile_cont(0.75) within GROUP (ORDER BY COUNT(DISTINCT p.procedure_id)) AS percentile FROM physionet-data.mimiciv_3_1_hosp.patients p JOIN physionet-data.mimiciv_3_1_hosp.procedureevents e ON p.subject_id = e.subject_id WHERE p.gender = 1 AND p.age >= 63 AND p.age <= 73 AND e.itemid IN (SELECT itemid FROM physionet-data.mimiciv_3_1_hosp.d_items WHERE category = 'cardiac');